export interface NavPage {
  path: string;
  title: string;
  /** One-line description shown under the H1 on the page itself. */
  description: string;
}

export interface NavGroup {
  /** Which guide the group belongs to; the sidebar shows a heading per guide. */
  section: "User guide" | "Developer guide";
  label: string;
  pages: NavPage[];
}

// The single source of truth for the site's structure: the left sidebar, the
