export const flatPages: NavPage[] = nav.flatMap((g) => g.pages);

export function findGroup(path: string): NavGroup | undefined {
  return nav.find((g) => g.pages.some((p) => p.path === path));
}

export function findPage(path: string): NavPage | undefined {
  return flatPages.find((p) => p.path === path);
}

export function prevNext(path: string): { prev?: NavPage; next?: NavPage } {
  const i = flatPages.findIndex((p) => p.path === path);
  if (i === -1) return {};
  return { prev: flatPages[i - 1], next: flatPages[i + 1] };
}

